from typing import Any


def _place(name: str, description: str, latitude: float, longitude: float, category: str) -> dict[str, Any]:
    return {"name": name, "description": description, "latitude": latitude, "longitude": longitude, "category": category}


def _food(name: str, description: str, latitude: float, longitude: float, price: int) -> dict[str, Any]:
    return {"name": name, "description": description, "latitude": latitude, "longitude": longitude, "estimated_price_krw": price}


